def prove(goal, facts, rules):
    def go(goal, active):
        if goal in facts:
            return []
        if goal in active:
            return None
        for head, body, step in rules:
            if head != goal:
                continue
            plan, ok = [], True
            for sub in body:
                sub_plan = go(sub, active | {goal})
                if sub_plan is None:
                    ok = False
                    break
                plan += sub_plan
            if ok:
                if step is not None:
                    plan.append(step)
                return plan
        return None

    steps = go(goal, frozenset())
    if steps is None:
        return None
    ordered = []
    for step in steps:
        if step not in ordered:
            ordered.append(step)
    return tuple(ordered)
